import { useCallback, useEffect, useState } from 'react';
import { supabase } from '@/integrations/supabase/client';

export type RecipeNodeKind = 'ficha' | 'produto_master' | 'insumo' | 'nf' | 'item';

export interface RawFicha {
  id: number;
  nome: string;
  custo_calculado: number | null;
  produto_master_id: number | null;
  status: string;
  rendimento_quantidade: number;
  rendimento_unidade: string;
}

export interface RawItem {
  id?: number;
  ficha_tecnica_id: number;
  produto_master_id: number | null;
  insumo_id: number | null;
  sub_ficha_id: number | null;
  observacao: string | null;
  quantidade: number;
  unidade: string;
  custo_calculado?: number | null;
  preco_unitario_esboco?: number | null;
}

export interface RawProduto {
  id: number;
  nome: string;
  codigo_interno: number | null;
  preco_custo: number | null;
  setor: string | null;
}

export interface RawInsumo {
  id: number;
  nome: string;
  preco_custo: number | null;
  unidade_compra: string | null;
  unidade_producao: string | null;
  fornecedor_principal: string | null;
  produto_master_id?: number | null;
  fator_conversao?: number | null;
}

export interface RawNF {
  id: number;
  fornecedor: string | null;
  numero_nota: string | null;
  valor_total: number | null;
  data_nota: string | null;
  is_esboco?: boolean;
}

export interface RawNFItem {
  id: number;
  nota_id: number;
  insumo_id: number | null;
  nome_produto: string | null;
  quantidade: number | null;
  valor_unitario: number | null;
  peso_unitario?: number | null;
  unidade_base?: string | null;
  unidade?: string | null;
}

export const fichaNodeId = (id: number) => `ficha_${id}`;
export const produtoNodeId = (id: number) => `produto_${id}`;
export const insumoNodeId = (id: number) => `insumo_${id}`;
export const nfNodeId = (id: number) => `nf_${id}`;

export function parseNodeId(
  key: string
): { type: RecipeNodeKind; id: number } | null {
  const idx = key.indexOf('_');
  if (idx < 0) return null;
  const type = key.slice(0, idx);
  const id = Number(key.slice(idx + 1));
  if (!Number.isFinite(id)) return null;
  if (type === 'ficha') return { type: 'ficha', id };
  if (type === 'produto') return { type: 'produto_master', id };
  if (type === 'insumo') return { type: 'insumo', id };
  if (type === 'nf') return { type: 'nf', id };
  if (type === 'item') return { type: 'item', id };
  return null;
}

export function useRecipeGraph(workspaceFichaId?: number | null) {
  const [loading, setLoading] = useState(true);
  const [fichas, setFichas] = useState<RawFicha[]>([]);
  const [items, setItems] = useState<RawItem[]>([]);
  const [produtos, setProdutos] = useState<RawProduto[]>([]);
  const [insumos, setInsumos] = useState<RawInsumo[]>([]);
  const [notas, setNotas] = useState<RawNF[]>([]);
  const [nfItems, setNfItems] = useState<RawNFItem[]>([]);
  const [positions, setPositions] = useState<Map<string, { x: number; y: number }>>(new Map());

  const fetchAll = useCallback(async () => {
    setLoading(true);
    try {
      // 1) Buscar positions DO WORKSPACE ATUAL (cada ficha = seu canvas isolado)
      // Se workspaceFichaId não definido, busca só positions de fichas (overview)
      const posQuery = supabase
        .from('recipe_canvas_positions')
        .select('node_type, node_id, x, y, workspace_ficha_id');
      const posRes = workspaceFichaId != null
        ? await posQuery.eq('workspace_ficha_id', workspaceFichaId)
        : await posQuery.eq('node_type', 'ficha');
      if (posRes.error) throw posRes.error;
      const nfIdsComPosicao = (posRes.data ?? [])
        .filter((p: { node_type: string }) => p.node_type === 'nf')
        .map((p: { node_id: number }) => p.node_id);

      // 2) Buscar tudo em paralelo (incluindo NFs com posição + recentes)
      const [fichasRes, itemsRes, insumosRes, nfRecentesRes, nfPositionsRes, nfItemsRes] = await Promise.all([
        supabase
          .from('fichas_tecnicas')
          .select(
            'id, nome, custo_calculado, produto_master_id, status, rendimento_quantidade, rendimento_unidade'
          )
          .neq('status', 'obsoleta')
          .order('nome'),
        supabase
          .from('ficha_tecnica_itens')
          .select(
            'id, ficha_tecnica_id, produto_master_id, insumo_id, sub_ficha_id, observacao, quantidade, unidade, custo_calculado, preco_unitario_esboco'
          ),
        supabase
          .from('insumos')
          .select('id, nome, preco_custo, unidade_compra, unidade_producao, fornecedor_principal, produto_master_id, fator_conversao')
          .eq('ativo', true)
          .order('nome'),
        supabase
          .from('notas_fiscais')
          .select('id, fornecedor, numero_nota, valor_total, data_nota, is_esboco')
          .order('data_nota', { ascending: false })
          .limit(80),
        // NFs antigas que já foram trazidas ao canvas (têm posição)
        nfIdsComPosicao.length > 0
          ? supabase
              .from('notas_fiscais')
              .select('id, fornecedor, numero_nota, valor_total, data_nota, is_esboco')
              .in('id', nfIdsComPosicao)
          : Promise.resolve({ data: [], error: null }),
        // Itens da NF: todos atrelados a algum insumo (essencial pra preço/edge)
        // + itens recentes (display de NFs novas)
        supabase
          .from('itens_nota_fiscal')
          .select('id, nota_id, insumo_id, nome_produto, quantidade, valor_unitario, peso_unitario, unidade_base, unidade')
          .or(`insumo_id.not.is.null${nfIdsComPosicao.length > 0 ? `,nota_id.in.(${nfIdsComPosicao.join(',')})` : ''}`)
          .order('id', { ascending: false })
          .limit(5000),
      ]);

      if (fichasRes.error) throw fichasRes.error;
      if (itemsRes.error) throw itemsRes.error;
      if (insumosRes.error) throw insumosRes.error;
      if (nfRecentesRes.error) throw nfRecentesRes.error;
      if (nfPositionsRes.error) throw nfPositionsRes.error;
      if (nfItemsRes.error) throw nfItemsRes.error;

      const f = (fichasRes.data ?? []) as RawFicha[];
      const i = (itemsRes.data ?? []) as RawItem[];
      const ins = (insumosRes.data ?? []) as RawInsumo[];
      // Merge NFs recentes + NFs com posição (dedup por id)
      const nfRecentes = (nfRecentesRes.data ?? []) as RawNF[];
      const nfComPosicao = (nfPositionsRes.data ?? []) as RawNF[];
      const nfMap = new Map<number, RawNF>();
      nfRecentes.forEach((x) => nfMap.set(x.id, x));
      nfComPosicao.forEach((x) => nfMap.set(x.id, x));
      const nf = Array.from(nfMap.values());
      const nfit = (nfItemsRes.data ?? []) as RawNFItem[];

      const pmIds = new Set<number>();
      f.forEach((x) => { if (x.produto_master_id) pmIds.add(x.produto_master_id); });
      i.forEach((x) => { if (x.produto_master_id) pmIds.add(x.produto_master_id); });

      let pms: RawProduto[] = [];
      if (pmIds.size > 0) {
        const { data, error } = await supabase
          .from('produtos_master')
          .select('id, nome, codigo_interno, preco_custo, setor')
          .in('id', Array.from(pmIds));
        if (error) throw error;
        pms = (data ?? []) as RawProduto[];
      }

      const pmap = new Map<string, { x: number; y: number }>();
      (posRes.data ?? []).forEach((p: { node_type: string; node_id: number; x: number; y: number }) => {
        let key = '';
        if (p.node_type === 'ficha') key = fichaNodeId(p.node_id);
        else if (p.node_type === 'produto_master') key = produtoNodeId(p.node_id);
        else if (p.node_type === 'insumo') key = insumoNodeId(p.node_id);
        else if (p.node_type === 'nf') key = nfNodeId(p.node_id);
        else if (p.node_type === 'item') key = `item_${p.node_id}`;
        if (key) pmap.set(key, { x: Number(p.x), y: Number(p.y) });
      });

      setFichas(f);
      setItems(i);
      setProdutos(pms);
      setInsumos(ins);
      setNotas(nf);
      setNfItems(nfit);
      setPositions(pmap);
    } finally {
      setLoading(false);
    }
  }, [workspaceFichaId]);

  useEffect(() => { fetchAll(); }, [fetchAll]);

  // Realtime: re-fetch quando algo muda no banco (debounced)
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout> | null = null;
    const debounced = () => {
      if (timer) clearTimeout(timer);
      timer = setTimeout(() => { fetchAll(); }, 350);
    };
    const channel = supabase
      .channel('recipe_graph_live')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'fichas_tecnicas' }, debounced)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'ficha_tecnica_itens' }, debounced)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'insumos' }, debounced)
      .subscribe();
    return () => {
      if (timer) clearTimeout(timer);
      supabase.removeChannel(channel);
    };
  }, [fetchAll]);

  const savePosition = useCallback(async (key: string, x: number, y: number) => {
    const parsed = parseNodeId(key);
    if (!parsed) return;
    // Workspace: ficha sempre é dona de si; insumo/nf/loose herdam workspaceFichaId
    let workspace_ficha_id: number;
    if (parsed.type === 'ficha') {
      workspace_ficha_id = parsed.id;
    } else if (workspaceFichaId != null) {
      workspace_ficha_id = workspaceFichaId;
    } else {
      console.warn('[savePosition] workspaceFichaId nulo pra node não-ficha; ignorando', { key });
      return;
    }
    const { error } = await supabase
      .from('recipe_canvas_positions')
      .upsert(
        {
          workspace_ficha_id,
          node_type: parsed.type,
          node_id: parsed.id,
          x, y,
          updated_at: new Date().toISOString(),
        },
        { onConflict: 'workspace_ficha_id,node_type,node_id' }
      );
    if (error) {
      console.error('[savePosition] erro:', error, { key, x, y, workspace_ficha_id });
      throw error;
    }
  }, [workspaceFichaId]);

  return {
    loading,
    fichas,
    items,
    produtos,
    insumos,
    notas,
    nfItems,
    positions,
    savePosition,
    refetch: fetchAll,
  };
}

