-- runtime test of cost function in a rolled-back transaction
BEGIN;
-- pick a real CMV, a real embalagem produto_master, and a real NF embalagem item
DO $$
DECLARE
  v_cmv_id bigint;
  v_pm_id  bigint;
  v_nf_id  bigint;
  v_nf_val numeric;
  v_item_id bigint;
  v_cost numeric;
  v_total_before numeric;
  v_total_after numeric;
BEGIN
  SELECT id, custo_calculado INTO v_cmv_id, v_total_before FROM cmv_fichas ORDER BY id LIMIT 1;
  IF v_cmv_id IS NULL THEN RAISE NOTICE 'NO CMV EXISTS - skipping'; RETURN; END IF;

  SELECT id INTO v_pm_id FROM produtos_master WHERE ativo AND setor='EMBALAGENS' ORDER BY id LIMIT 1;
  SELECT id, valor_unitario INTO v_nf_id, v_nf_val FROM itens_nota_fiscal WHERE categoria='Embalagens' AND valor_unitario>0 ORDER BY id DESC LIMIT 1;

  -- insert an embalagem item: NF travada, 200 unidades por embalagem, quantidade 1
  INSERT INTO cmv_itens(cmv_id, tipo, produto_master_id, nf_item_id, unidades_por_embalagem, quantidade, unidade, ordem)
  VALUES (v_cmv_id, 'embalagem', v_pm_id, v_nf_id, 200, 1, 'un', 999)
  RETURNING id INTO v_item_id;

  SELECT custo_calculado INTO v_cost FROM cmv_itens WHERE id = v_item_id;
  SELECT custo_calculado INTO v_total_after FROM cmv_fichas WHERE id = v_cmv_id;

  RAISE NOTICE 'NF valor_unitario=%, esperado custo item = % / 200 = %, custo_calculado gravado pelo trigger = %',
    v_nf_val, v_nf_val, round(v_nf_val/200, 6), v_cost;
  RAISE NOTICE 'CMV total antes=% depois=% (delta=%)', v_total_before, v_total_after, v_total_after - v_total_before;
END $$;
ROLLBACK;

