-- CMV = PRODUTO FINAL vendido (ex.: "Canjica 200ml no pote").
-- O node central do construtor de CMV representa o produto embalado/lacrado vendido.
-- Custo do produto final = contribuição da receita (ficha técnica base) + embalagens + avulsos.
--
-- Novidades:
--   * quantidade_ficha + unidade_ficha: QUANTO da receita base entra em 1 produto final
--     (ex.: 200 g de canjica), com conversão de unidade contra o rendimento da ficha
--     (ficha R$ 55,08/kg -> 200 g = R$ 11,02).
--   * rendimento_quantidade + rendimento_unidade: tamanho/unidade do item vendido (ex.: 200 ml).
--     DESCRITIVO apenas — rótulo + base para exibir custo por unidade. NÃO entra no custo.
--
-- Retrocompat total: quando quantidade_ficha IS NULL, a contribuição da ficha permanece
-- "1 unidade do rendimento da ficha" (custo_calculado / rendimento_quantidade), idêntica ao
-- comportamento anterior. Recompute continua via trigger cmv_item_recompute_trg (guard
-- app.in_cmv_recompute evita recursão).

-- ============================================================
-- 1. NOVAS COLUNAS em cmv_fichas (NULL — registros existentes inalterados)
-- ============================================================
ALTER TABLE public.cmv_fichas
  ADD COLUMN IF NOT EXISTS rendimento_quantidade numeric,
  ADD COLUMN IF NOT EXISTS rendimento_unidade    text,
  ADD COLUMN IF NOT EXISTS quantidade_ficha      numeric,
  ADD COLUMN IF NOT EXISTS unidade_ficha         text;

-- ============================================================
-- 2. REESCRITA de recompute_cmv_cost — contribuição da ficha base com quantidade + conversão
-- ============================================================
CREATE OR REPLACE FUNCTION public.recompute_cmv_cost(p_cmv_id bigint)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_item_id         bigint;
  v_new_cost        numeric;
  v_itens_total     numeric := 0;
  v_ficha_unit_cost numeric := 0;   -- R$ por unidade de rendimento da ficha (ex.: R$/kg)
  v_ficha_contrib   numeric := 0;   -- contribuição da receita no produto final
  v_total           numeric := 0;
  v_old_total       numeric;
  v_ficha_id        bigint;
  v_ficha_custo     numeric;
  v_ficha_rend      numeric;        -- rendimento_quantidade da ficha
  v_ficha_rend_un   text;           -- rendimento_unidade da ficha
  v_qtd_ficha       numeric;        -- quanto da receita entra em 1 produto final
  v_un_ficha        text;           -- unidade dessa quantidade
  v_ratio           numeric := 1.0;
  v_uf              text;           -- unidade da quantidade consumida (lower)
  v_ui              text;           -- unidade de rendimento da ficha (lower)
  v_was_in          text;
BEGIN
  v_was_in := current_setting('app.in_cmv_recompute', true);
  PERFORM set_config('app.in_cmv_recompute', 'true', true);

  -- recomputa cada item (embalagem / avulso)
  FOR v_item_id IN SELECT id FROM cmv_itens WHERE cmv_id = p_cmv_id LOOP
    v_new_cost := cmv_compute_item_cost(v_item_id);
    UPDATE cmv_itens SET custo_calculado = v_new_cost, updated_at = now()
     WHERE id = v_item_id;
    v_itens_total := v_itens_total + coalesce(v_new_cost, 0);
  END LOOP;

  -- dados da ficha base + parâmetros do produto final
  SELECT cf.ficha_tecnica_id, ft.custo_calculado, ft.rendimento_quantidade,
         ft.rendimento_unidade, cf.quantidade_ficha, cf.unidade_ficha
    INTO v_ficha_id, v_ficha_custo, v_ficha_rend, v_ficha_rend_un,
         v_qtd_ficha, v_un_ficha
    FROM cmv_fichas cf
    JOIN fichas_tecnicas ft ON ft.id = cf.ficha_tecnica_id
   WHERE cf.id = p_cmv_id;

  IF v_ficha_id IS NOT NULL AND coalesce(v_ficha_rend, 0) > 0 THEN
    v_ficha_unit_cost := coalesce(v_ficha_custo, 0) / v_ficha_rend;

    IF v_qtd_ficha IS NULL THEN
      -- retrocompat: 1 unidade do rendimento da ficha
      v_ficha_contrib := v_ficha_unit_cost;
    ELSE
      -- conversão da unidade consumida -> unidade de rendimento da ficha
      v_uf := lower(coalesce(v_un_ficha, ''));
      v_ui := lower(coalesce(v_ficha_rend_un, ''));
      IF    v_uf = v_ui THEN                       v_ratio := 1.0;
      ELSIF v_uf = 'g'  AND v_ui = 'kg' THEN       v_ratio := 0.001;
      ELSIF v_uf = 'kg' AND v_ui = 'g'  THEN       v_ratio := 1000;
      ELSIF v_uf = 'ml' AND v_ui = 'l'  THEN       v_ratio := 0.001;
      ELSIF v_uf = 'l'  AND v_ui = 'ml' THEN       v_ratio := 1000;
      ELSIF v_uf = 'mg' AND v_ui = 'g'  THEN       v_ratio := 0.001;
      ELSIF v_uf = 'g'  AND v_ui = 'mg' THEN       v_ratio := 1000;
      ELSE                                          v_ratio := 1.0;
      END IF;
      v_ficha_contrib := v_ficha_unit_cost * v_qtd_ficha * v_ratio;
    END IF;
  END IF;

  -- rendimento_quantidade/rendimento_unidade do PRODUTO FINAL são descritivos: não entram aqui
  v_total := v_ficha_contrib + v_itens_total;

  SELECT custo_calculado INTO v_old_total FROM cmv_fichas WHERE id = p_cmv_id;
  IF v_old_total IS DISTINCT FROM v_total THEN
    UPDATE cmv_fichas SET custo_calculado = v_total, updated_at = now()
     WHERE id = p_cmv_id;
  END IF;

  PERFORM set_config('app.in_cmv_recompute', coalesce(v_was_in, 'false'), true);
END;
$function$;

-- ============================================================
-- 3. Backfill defensivo (idempotente — totais existentes idênticos: quantidade_ficha é NULL)
-- ============================================================
DO $$
DECLARE v_id bigint;
BEGIN
  FOR v_id IN SELECT id FROM public.cmv_fichas LOOP
    PERFORM public.recompute_cmv_cost(v_id);
  END LOOP;
END $$;

-- RLS: nenhuma mudança. Colunas pertencem à própria linha de cmv_fichas (policy existente cobre).

-- DOWN (referência):
--   ALTER TABLE public.cmv_fichas
--     DROP COLUMN IF EXISTS unidade_ficha, DROP COLUMN IF EXISTS quantidade_ficha,
--     DROP COLUMN IF EXISTS rendimento_unidade, DROP COLUMN IF EXISTS rendimento_quantidade;
--   -- restaurar recompute_cmv_cost da migration 20260612160000 §recompute

