CREATE OR REPLACE FUNCTION public.tg_cmv_fichas_recompute()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF current_setting('app.in_cmv_recompute', true) = 'true' THEN
    RETURN NEW;
  END IF;
  PERFORM recompute_cmv_cost(NEW.id);
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS cmv_fichas_recompute_trg ON public.cmv_fichas;
CREATE TRIGGER cmv_fichas_recompute_trg
  AFTER UPDATE OF quantidade_ficha, unidade_ficha ON public.cmv_fichas
  FOR EACH ROW
  WHEN (OLD.quantidade_ficha IS DISTINCT FROM NEW.quantidade_ficha
        OR OLD.unidade_ficha IS DISTINCT FROM NEW.unidade_ficha)
  EXECUTE FUNCTION public.tg_cmv_fichas_recompute();

BEGIN;
UPDATE cmv_fichas SET quantidade_ficha = 200, unidade_ficha = 'g' WHERE id = 1;
-- sem chamar recompute manual: o trigger deve ter recalculado
SELECT custo_calculado AS total_apos_trigger,
       round(594.8866/10.8 * 200 * 0.001, 4) AS esperado
FROM cmv_fichas WHERE id = 1;
ROLLBACK;

