import { useEffect, useState } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';
import {
  Loader2, Receipt, Sparkles, Calendar, ExternalLink, Check, Pencil, Wand2,
} from 'lucide-react';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter,
} from '@/shared/ui/dialog';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from '@/shared/ui/select';
import { useNavigate } from 'react-router-dom';
import type { RawInsumo } from '@/hooks/producao/useRecipeGraph';

const UNIDADES_BASE_NF = ['kg', 'g', 'L', 'mL', 'un'] as const;

/** Tenta extrair peso e unidade do nome do produto (ex: "PASTA 25 KG" → {peso:25, unidade:'kg'}) */
function autoDetectPeso(nome: string | null): { peso: number; unidade: string } | null {
  if (!nome) return null;
  const m = nome.match(/(\d+(?:[.,]\d+)?)\s*(KG|G|L|ML|UN|UNIDADE|PACK)\b/i);
  if (!m) return null;
  const peso = Number(m[1].replace(',', '.'));
  if (!Number.isFinite(peso) || peso <= 0) return null;
  let unidade = m[2].toLowerCase();
  if (unidade === 'unidade') unidade = 'un';
  return { peso, unidade };
}

const fmtBRL = (n: number) =>
  n.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

const fmtDate = (d?: string | null) => {
  if (!d) return '—';
  try { return new Date(d).toLocaleDateString('pt-BR'); } catch { return d; }
};

interface NFFull {
  id: number;
  fornecedor: string | null;
  numero_nota: string | null;
  valor_total: number | null;
  data_nota: string | null;
  is_esboco: boolean;
}
interface NFItemFull {
  id: number;
  nota_id: number;
  nome_produto: string | null;
  quantidade: number | null;
  valor_unitario: number | null;
  subtotal: number | null;
  insumo_id: number | null;
  peso_unitario: number | null;
  unidade_base: string | null;
}

interface EditNFDialogProps {
  open: boolean;
  nfId: number | null;
  insumos: RawInsumo[];
  onClose: () => void;
  onSaved: () => void; // mantido por compat — não usado em modo read-only
}

/**
 * Visualizador de NF (READ-ONLY).
 * Não permite editar — pra mudar uma NF real, ir na página de NFs.
 * A unidade de conversão é configurada NO INSUMO, não aqui.
 */
export function EditNFDialog({ open, nfId, insumos, onClose }: EditNFDialogProps) {
  const [loading, setLoading] = useState(false);
  const [nf, setNF] = useState<NFFull | null>(null);
  const [items, setItems] = useState<NFItemFull[]>([]);
  const navigate = useNavigate();

  useEffect(() => {
    if (!open || nfId == null) {
      setNF(null);
      setItems([]);
      return;
    }
    setLoading(true);
    (async () => {
      const [nfRes, itensRes] = await Promise.all([
        supabase
          .from('notas_fiscais')
          .select('id, fornecedor, numero_nota, valor_total, data_nota, is_esboco')
          .eq('id', nfId)
          .single(),
        supabase
          .from('itens_nota_fiscal')
          .select('id, nota_id, nome_produto, quantidade, valor_unitario, subtotal, insumo_id, peso_unitario, unidade_base')
          .eq('nota_id', nfId)
          .order('id'),
      ]);
      if (nfRes.error) {
        toast.error('Erro ao carregar NF');
        setLoading(false);
        return;
      }
      setNF(nfRes.data as NFFull);
      setItems((itensRes.data ?? []) as NFItemFull[]);
      setLoading(false);
    })();
  }, [open, nfId]);

  if (!open) return null;

  const totalReal = items.reduce(
    (s, it) =>
      s + (Number(it.subtotal) || (Number(it.quantidade) || 0) * (Number(it.valor_unitario) || 0)),
    0
  );

  const isEsboco = nf?.is_esboco === true;

  return (
    <Dialog open={open} onOpenChange={(o) => !o && onClose()}>
      <DialogContent className="max-w-xl max-h-[88vh] flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Receipt className={`h-4 w-4 ${isEsboco ? 'text-orange-500' : 'text-blue-500'}`} />
            {isEsboco ? 'NF Esboço' : 'Nota Fiscal'}
            <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-normal">
              · somente leitura
            </span>
          </DialogTitle>
        </DialogHeader>

        {loading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-6 w-6 animate-spin text-blue-500" />
          </div>
        ) : !nf ? (
          <div className="py-12 text-center text-sm text-muted-foreground">NF não encontrada.</div>
        ) : (
          <div className="flex-1 overflow-y-auto space-y-3 py-2">
            {isEsboco && (
              <div className="rounded-lg bg-orange-50 dark:bg-orange-950/30 p-2.5 text-[11px] flex items-start gap-2">
                <Sparkles className="h-3.5 w-3.5 text-orange-500 shrink-0 mt-0.5" />
                <p className="text-orange-700 dark:text-orange-300">
                  NF em modo esboço (planejamento). Vai virar NF real quando lançada de verdade.
                </p>
              </div>
            )}

            {/* Cabeçalho NF */}
            <div className="grid grid-cols-2 gap-3 rounded-lg border border-border p-3 bg-slate-50/50 dark:bg-slate-800/30">
              <div>
                <p className="text-[10px] uppercase tracking-wider text-muted-foreground">Fornecedor</p>
                <p className="text-sm font-semibold truncate">{nf.fornecedor ?? '—'}</p>
              </div>
              <div>
                <p className="text-[10px] uppercase tracking-wider text-muted-foreground">Número NF</p>
                <p className="text-sm font-mono">{nf.numero_nota ?? '—'}</p>
              </div>
              <div>
                <p className="text-[10px] uppercase tracking-wider text-muted-foreground">Data</p>
                <p className="text-sm flex items-center gap-1">
                  <Calendar className="h-3 w-3 text-muted-foreground" />
                  {fmtDate(nf.data_nota)}
                </p>
              </div>
              <div>
                <p className="text-[10px] uppercase tracking-wider text-muted-foreground">Valor total</p>
                <p className="text-sm font-bold tabular-nums text-blue-700 dark:text-blue-300">
                  {fmtBRL(totalReal || Number(nf.valor_total) || 0)}
                </p>
              </div>
            </div>

            {/* Items da NF — read only */}
            <div>
              <p className="text-[10px] uppercase tracking-wider text-muted-foreground font-bold px-1 mb-1.5">
                Itens da NF ({items.length})
              </p>
              <div className="space-y-1.5">
                {items.length === 0 && (
                  <div className="text-center py-6 text-sm text-muted-foreground">
                    Sem itens nesta NF.
                  </div>
                )}
                {items.map((it, idx) => (
                  <NFItemRow
                    key={it.id}
                    item={it}
                    insumo={it.insumo_id ? insumos.find((i) => i.id === it.insumo_id) ?? null : null}
                    onUpdate={(patch) => {
                      setItems((prev) =>
                        prev.map((x, i) => (i === idx ? { ...x, ...patch } : x))
                      );
                    }}
                  />
                ))}
              </div>
            </div>

            <div className="rounded-lg bg-blue-50/50 dark:bg-blue-950/20 border border-blue-200 dark:border-blue-800/40 p-2.5 text-[11px] text-blue-700 dark:text-blue-300">
              💡 <strong>Pra ajustar unidades (kg/g, pack/un, etc.)</strong>: clique no node do <strong>Insumo</strong> no canvas
              → bloco "Unidades & Conversão" → Editar. A NF fica intocada.
            </div>
          </div>
        )}

        <DialogFooter className="border-t border-border pt-3">
          {!isEsboco && nf && (
            <Button
              variant="ghost"
              onClick={() => navigate('/notas-fiscais')}
              className="mr-auto"
            >
              <ExternalLink className="mr-1.5 h-3.5 w-3.5" />
              Abrir na página de NFs
            </Button>
          )}
          <Button data-mia-action="close" variant="outline" onClick={onClose}>Fechar</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/* ──────────────────────────────────────────────────────────────
   NFItemRow — uma linha (item) da NF, com config de peso/unidade
   ────────────────────────────────────────────────────────────── */

interface NFItemRowProps {
  item: NFItemFull;
  insumo: RawInsumo | null;
  onUpdate: (patch: Partial<NFItemFull>) => void;
}

function NFItemRow({ item, insumo, onUpdate }: NFItemRowProps) {
  const [editing, setEditing] = useState(false);
  const [peso, setPeso] = useState<number>(Number(item.peso_unitario) || 0);
  const [unidade, setUnidade] = useState<string>(item.unidade_base ?? 'kg');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    setPeso(Number(item.peso_unitario) || 0);
    setUnidade(item.unidade_base ?? 'kg');
  }, [item.peso_unitario, item.unidade_base]);

  const qty = Number(item.quantidade) || 0;
  const valorUnit = Number(item.valor_unitario) || 0;
  const subtotal = Number(item.subtotal) || qty * valorUnit;
  const pesoTotal = peso > 0 ? qty * peso : 0;
  const precoEfetivo = peso > 0 ? valorUnit / peso : 0;

  const handleAutoDetect = () => {
    const det = autoDetectPeso(item.nome_produto);
    if (det) {
      setPeso(det.peso);
      setUnidade(det.unidade);
      toast.success(`Detectei: ${det.peso} ${det.unidade}`);
    } else {
      toast.error('Não consegui detectar — informe manualmente');
    }
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      const { error } = await supabase
        .from('itens_nota_fiscal')
        .update({ peso_unitario: peso > 0 ? peso : null, unidade_base: unidade })
        .eq('id', item.id);
      if (error) throw error;
      toast.success('Peso configurado — preço do insumo sincronizado');
      onUpdate({ peso_unitario: peso > 0 ? peso : null, unidade_base: unidade });
      setEditing(false);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Erro ao salvar');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="rounded-lg border border-border p-3 bg-white dark:bg-slate-900 space-y-2">
      {/* Linha topo: nome + subtotal */}
      <div className="flex items-start justify-between gap-2">
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium leading-snug">{item.nome_produto ?? '—'}</p>
          <p className="text-[10px] text-muted-foreground mt-0.5 tabular-nums">
            {qty} × {fmtBRL(valorUnit)}
          </p>
        </div>
        <div className="text-right shrink-0">
          <p className="text-base font-bold tabular-nums text-emerald-700 dark:text-emerald-300">
            {fmtBRL(subtotal)}
          </p>
          <p className="text-[9px] text-muted-foreground">total pago</p>
        </div>
      </div>

      {/* Config peso/unidade */}
      <div className="rounded-md bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-800/40 p-2 text-[11px]">
        {!editing ? (
          <div className="flex items-center justify-between gap-2">
            {peso > 0 ? (
              <div>
                <p className="text-amber-700 dark:text-amber-300">
                  📦 Cada unidade = <strong>{peso} {unidade}</strong>
                </p>
                <p className="text-[10px] text-emerald-700 dark:text-emerald-300 tabular-nums">
                  ⇒ {qty} × {peso}{unidade} = <strong>{pesoTotal} {unidade}</strong> total · {fmtBRL(precoEfetivo)}/{unidade}
                </p>
              </div>
            ) : (
              <p className="text-orange-700 dark:text-orange-300">
                ⚠ Configure o peso por unidade pra calcular R$/{unidade} correto
              </p>
            )}
            <button
              onClick={() => setEditing(true)}
              className="text-[10px] text-amber-700 dark:text-amber-300 font-bold flex items-center gap-1 hover:underline"
            >
              <Pencil className="h-2.5 w-2.5" />
              {peso > 0 ? 'Editar' : 'Configurar'}
            </button>
          </div>
        ) : (
          <div className="space-y-2">
            <div className="grid grid-cols-3 gap-2 items-end">
              <div>
                <Label className="text-[9px] text-muted-foreground">Peso/un</Label>
                <Input data-mia-field="peso"
                  type="number" min={0} step="any"
                  className="h-7 text-xs"
                  value={peso || ''}
                  onChange={(e) => setPeso(e.target.value)}
                />
              </div>
              <div>
                <Label className="text-[9px] text-muted-foreground">Unidade</Label>
                <Select value={unidade} onValueChange={setUnidade}>
                  <SelectTrigger data-mia-filter="unidade" className="h-7 text-xs"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {UNIDADES_BASE_NF.map((u) => <SelectItem key={u} value={u}>{u}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
              <button
                onClick={handleAutoDetect}
                className="h-7 px-2 rounded text-[10px] bg-blue-500 hover:bg-blue-600 text-white flex items-center justify-center gap-1"
                title="Auto-detectar do nome do produto"
              >
                <Wand2 className="h-3 w-3" />
                Auto
              </button>
            </div>
            {peso > 0 && (
              <p className="text-[10px] tabular-nums text-emerald-700 dark:text-emerald-300">
                Preview: {qty} × {peso}{unidade} = <strong>{pesoTotal} {unidade}</strong> · {fmtBRL(precoEfetivo)}/{unidade}
              </p>
            )}
            <div className="flex gap-1 justify-end">
              <button
                onClick={() => { setEditing(false); setPeso(Number(item.peso_unitario) || 0); setUnidade(item.unidade_base ?? 'kg'); }}
                className="text-[10px] text-muted-foreground hover:text-foreground px-2"
                disabled={saving}
              >
                Cancelar
              </button>
              <button
                onClick={handleSave}
                disabled={saving}
                className="text-[10px] bg-amber-500 hover:bg-amber-600 text-white px-2 py-0.5 rounded flex items-center gap-1"
              >
                {saving ? <Loader2 className="h-2.5 w-2.5 animate-spin" /> : <Check className="h-2.5 w-2.5" />}
                Salvar
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Status atrelagem */}
      {insumo ? (
        <p className="text-[10px] text-emerald-600 dark:text-emerald-400 flex items-center gap-1">
          🔗 Atrelado: <strong>{insumo.nome}</strong>
        </p>
      ) : (
        <p className="text-[10px] text-muted-foreground italic">
          Não atrelado — arraste a NF no canvas até o insumo correspondente
        </p>
      )}
    </div>
  );
}

