-- CMV: o TAMANHO do produto final (rendimento_quantidade + rendimento_unidade, ex.: 200 ml)
-- passa a DIRIGIR o custo da receita automaticamente — como o rendimento nas fichas técnicas.
-- Você informa "200 ml" e o sistema calcula o custo da receita para 200 ml:
--   contribuição_receita = custo_total_da_ficha × (base_do_produto / base_da_ficha)
-- onde base = quantidade × fator de unidade (kg/l=1000, g/ml=1, mg=0,001, demais=1).
-- ml≈g e l≈kg (densidade ~1, adequado a doces/líquidos da Momma).
-- Não há mais campo separado de "quantidade da receita": o tamanho do produto é o driver.
--
-- Custo do produto final = contribuição_receita + embalagens + custos avulsos.
-- Retrocompat: se rendimento_quantidade IS NULL → contribuição = custo/rendimento da ficha
-- (1 unidade), idêntico ao comportamento anterior.

-- 1. Helper de fator de unidade -> base comum (g/ml). Densidade ~1 (ml=g, l=kg).
CREATE OR REPLACE FUNCTION public.cmv_unit_base_factor(p_unit text)
RETURNS numeric
LANGUAGE sql
IMMUTABLE
AS $function$
  SELECT CASE lower(coalesce(p_unit, ''))
    WHEN 'kg' THEN 1000
    WHEN 'l'  THEN 1000
    WHEN 'g'  THEN 1
    WHEN 'ml' THEN 1
    WHEN 'mg' THEN 0.001
    ELSE 1
  END;
$function$;

-- 2. Reescrita de recompute_cmv_cost: rendimento do produto dirige o custo da receita.
CREATE OR REPLACE FUNCTION public.recompute_cmv_cost(p_cmv_id bigint)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_item_id        bigint;
  v_new_cost       numeric;
  v_itens_total    numeric := 0;
  v_ficha_contrib  numeric := 0;
  v_total          numeric := 0;
  v_old_total      numeric;
  v_ficha_id       bigint;
  v_ficha_custo    numeric;
  v_ficha_rend     numeric;
  v_ficha_rend_un  text;
  v_prod_rend      numeric;
  v_prod_rend_un   text;
  v_recipe_base    numeric;
  v_prod_base      numeric;
  v_was_in         text;
BEGIN
  v_was_in := current_setting('app.in_cmv_recompute', true);
  PERFORM set_config('app.in_cmv_recompute', 'true', true);

  FOR v_item_id IN SELECT id FROM cmv_itens WHERE cmv_id = p_cmv_id LOOP
    v_new_cost := cmv_compute_item_cost(v_item_id);
    UPDATE cmv_itens SET custo_calculado = v_new_cost, updated_at = now()
     WHERE id = v_item_id;
    v_itens_total := v_itens_total + coalesce(v_new_cost, 0);
  END LOOP;

  SELECT cf.ficha_tecnica_id, ft.custo_calculado, ft.rendimento_quantidade,
         ft.rendimento_unidade, cf.rendimento_quantidade, cf.rendimento_unidade
    INTO v_ficha_id, v_ficha_custo, v_ficha_rend, v_ficha_rend_un,
         v_prod_rend, v_prod_rend_un
    FROM cmv_fichas cf
    JOIN fichas_tecnicas ft ON ft.id = cf.ficha_tecnica_id
   WHERE cf.id = p_cmv_id;

  IF v_ficha_id IS NOT NULL AND coalesce(v_ficha_rend, 0) > 0 THEN
    IF v_prod_rend IS NOT NULL AND v_prod_rend > 0 THEN
      -- tamanho do produto dirige o custo da receita
      v_recipe_base := v_ficha_rend * cmv_unit_base_factor(v_ficha_rend_un);
      v_prod_base   := v_prod_rend  * cmv_unit_base_factor(v_prod_rend_un);
      IF v_recipe_base > 0 THEN
        v_ficha_contrib := coalesce(v_ficha_custo, 0) * (v_prod_base / v_recipe_base);
      END IF;
    ELSE
      -- retrocompat: 1 unidade do rendimento da ficha
      v_ficha_contrib := coalesce(v_ficha_custo, 0) / v_ficha_rend;
    END IF;
  END IF;

  v_total := v_ficha_contrib + v_itens_total;

  SELECT custo_calculado INTO v_old_total FROM cmv_fichas WHERE id = p_cmv_id;
  IF v_old_total IS DISTINCT FROM v_total THEN
    UPDATE cmv_fichas SET custo_calculado = v_total, updated_at = now()
     WHERE id = p_cmv_id;
  END IF;

  PERFORM set_config('app.in_cmv_recompute', coalesce(v_was_in, 'false'), true);
END;
$function$;

-- 3. Trigger recalcula ao mudar o rendimento do produto (além de quantidade_ficha legado).
DROP TRIGGER IF EXISTS cmv_fichas_recompute_trg ON public.cmv_fichas;
CREATE TRIGGER cmv_fichas_recompute_trg
  AFTER UPDATE OF rendimento_quantidade, rendimento_unidade, quantidade_ficha, unidade_ficha
  ON public.cmv_fichas
  FOR EACH ROW
  WHEN (OLD.rendimento_quantidade IS DISTINCT FROM NEW.rendimento_quantidade
        OR OLD.rendimento_unidade  IS DISTINCT FROM NEW.rendimento_unidade
        OR OLD.quantidade_ficha    IS DISTINCT FROM NEW.quantidade_ficha
        OR OLD.unidade_ficha       IS DISTINCT FROM NEW.unidade_ficha)
  EXECUTE FUNCTION public.tg_cmv_fichas_recompute();

-- 4. Backfill idempotente.
DO $$
DECLARE v_id bigint;
BEGIN
  FOR v_id IN SELECT id FROM public.cmv_fichas LOOP
    PERFORM public.recompute_cmv_cost(v_id);
  END LOOP;
END $$;

